    97	                throw new IllegalArgumentException("--output must be provided");
    98	            }
    99	            output.writeAsText(outputPath, FileSystem.WriteMode.OVERWRITE).setParallelism(1);
   100	        }
   101	
   102	        env.execute("LongestSessionPerJob");
   103	    }
