   105	    /**
   106	     * Tracks the maximum stage task-count seen per job and emits exactly one
   107	     * record per job when the event-time watermark reaches end-of-stream.
   108	     */
   109	    public static class MaxCountProcess
   110	            extends KeyedProcessFunction<Long, Tuple2<Long, Long>, Tuple2<Long, Long>> {
   111	
   112	        // Timers at Long.MAX_VALUE are not supported; subtract one so the MAX
   113	        // watermark injected at end-of-stream still fires the timer.
   114	        private static final long END_OF_TIME = Long.MAX_VALUE - 1L;
   115	
   116	        private transient ValueState<Long> maxState;
   117	
   118	        @Override
   119	        public void open(Configuration cfg) {
   120	            maxState = getRuntimeContext().getState(
   121	                    new ValueStateDescriptor<>("maxStageTasks", Long.class));
   122	        }
   123	
   124	        @Override
   125	        public void processElement(Tuple2<Long, Long> value,
   126	                                   Context ctx,
   127	                                   Collector<Tuple2<Long, Long>> out) throws Exception {
   128	            Long cur = maxState.value();
   129	            if (cur == null || value.f1 > cur) {
   130	                maxState.update(value.f1);
   131	            }
   132	            ctx.timerService().registerEventTimeTimer(END_OF_TIME);
   133	        }
   134	
   135	        @Override
   136	        public void onTimer(long timestamp,
   137	                            OnTimerContext ctx,
   138	                            Collector<Tuple2<Long, Long>> out) throws Exception {
   139	            Long v = maxState.value();
   140	            if (v != null) {
   141	                out.collect(Tuple2.of(ctx.getCurrentKey(), v));
   142	            }
   143	        }
   144	    }
