   155	        @Override
   156	        public void run(SourceContext<TaskEvent> ctx) throws Exception {
   157	            if (path == null) {
   158	                return;
   159	            }
   160	            try (BufferedReader reader = new BufferedReader(
   161	                    new InputStreamReader(
   162	                            new GZIPInputStream(new FileInputStream(path)),
   163	                            StandardCharsets.UTF_8))) {
   164	                String line;
   165	                while (running && (line = reader.readLine()) != null) {
   166	                    TaskEvent e = TaskEvent.fromCSV(line);
   167	                    if (e != null) {
   168	                        ctx.collect(e);
   169	                    }
   170	                }
   171	            }
   172	        }
   173	
   174	        @Override
   175	        public void cancel() {
